import asyncio
import json
import re
from playwright.async_api import async_playwright, Page, Frame

class CheckoutEngine:
    def __init__(self, websocket_manager):
        self.manager = websocket_manager
        self.browser = None
        self.context = None
        self.page = None

    async def find_input(self, page_or_frame, keywords):
        try:
            inputs = await page_or_frame.query_selector_all('input')
            for inp in inputs:
                name = await inp.get_attribute('name') or ''
                id_attr = await inp.get_attribute('id') or ''
                placeholder = await inp.get_attribute('placeholder') or ''
                label = await inp.get_attribute('aria-label') or ''
                combined = f"{name} {id_attr} {placeholder} {label}".lower()
                if any(k in combined for k in keywords):
                    return inp

            frames = page_or_frame.frames
            for frame in frames:
                if frame == page_or_frame:
                    continue
                found = await self.find_input(frame, keywords)
                if found:
                    return found
        except Exception:
            pass
        return None

    async def smart_fill(self, card_data):
        await asyncio.sleep(2)
        mappings = {
            "number": (['card', 'cc', 'num', 'pan', 'credit'], card_data.number),
            "expiry": (['exp', 'date', 'mm', 'yy', 'valid'], card_data.expiry),
            "cvc": (['cvc', 'cvv', 'sec', 'code'], card_data.cvc),
            "name": (['name', 'holder', 'first', 'full'], card_data.name)
        }

        for field_type, (keywords, value) in mappings.items():
            element = await self.find_input(self.page, keywords)
            if element:
                await element.click()
                await element.fill('')
                await self.page.keyboard.type(value, delay=50)

        await asyncio.sleep(1)

    async def detect_3ds_and_proxy(self, session_id):
        try:
            await self.page.wait_for_load_state('networkidle', timeout=5000)
            content = await self.page.content()

            if "password" in content.lower() or "code" in content.lower() or "secure" in content.lower():
                await self.manager.send_message(session_id, {"type": "3ds_challenge", "html": content})

                response = await self.manager.wait_for_response(session_id)
                if response and 'otp' in response:
                    otp_input = await self.find_input(self.page, ['code', 'otp', 'password', 'pin'])
                    if otp_input:
                        await otp_input.fill(response['otp'])
                        await self.page.keyboard.press('Enter')
                        return True
            return False
        except Exception:
            return False

    async def run_checkout(self, url, card_data, session_id):
        async with async_playwright() as p:
            self.browser = await p.chromium.launch(headless=False, args=['--disable-blink-features=AutomationControlled'])
            self.context = await self.browser.new_context(
                user_agent="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.0.0 Safari/537.36"
            )
            self.page = await self.context.new_page()

            try:
                await self.page.goto(url, timeout=60000)
                await self.smart_fill(card_data)

                submit_btns = await self.page.query_selector_all('button, input[type="submit"]')
                for btn in submit_btns:
                    text = await btn.inner_text()
                    if any(x in text.lower() for x in ['pay', 'buy', 'confirm', 'submit']):
                        await btn.click()
                        break

                await asyncio.sleep(5)

                is_3ds = await self.detect_3ds_and_proxy(session_id)
                if is_3ds:
                    await self.page.wait_for_url('**/success**', timeout=60000)

                return {"status": "success", "final_url": self.page.url}

            except Exception as e:
                return {"status": "error", "message": str(e)}
            finally:
                await self.browser.close()
